        .merge(results_metadata)
        .fallback(errors::protocol_not_found)
        .layer(middleware::from_fn_with_state(
            shared.clone(),
            resolve_runner_identity,
        ))
        .layer(TraceLayer::new_for_http())
        .layer(middleware::from_fn(errors::protocol_error_envelope))
        .layer(middleware::from_fn_with_state(
            state.clone(),
