/// Programmatic classification of [`ApiError`]s, independent of the rendered
/// message text. Handlers that need to branch on a specific failure (rather
/// than parse a message) match on this.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub(crate) enum ApiErrorKind {
    /// Default classification for all ordinary errors.
    #[default]
    BadRequest,
    /// A submitted workflow's trigger filters rejected the event.
    TriggerMismatch,
}

/// API error.
#[derive(Debug)]
pub struct ApiError {
    status: StatusCode,
    message: String,
    kind: ApiErrorKind,
}
